INSERT INTO grammar.content_catalog_topics(version,slug,catalog_hash,payload)
SELECT 'core-2026-09-v4','contrast-concession','87b630c771d79eac83e3be02f06e226cf9455e201ca4d4e9ebd574542396373d',payload || '{"slug":"contrast-concession","title":"Contrast and concession: although, despite and whereas","level":"B2","order":46,"summary":"Show that two ideas contrast, or that something happens in spite of an obstacle.","guidance":"Read the form and meaning together. Study the contrasts, then explain a worked example in your own words before starting a fresh practice session.","learningGoals":["Although and even though","Despite and in spite of","Whereas and while","However and nevertheless"],"rules":[{"title":"Although and even though","explanation":"Although, though and even though introduce a subordinate clause. They present information that contrasts with the main clause or might have led to a different expectation. Even though often makes the contrast stronger.","pattern":"**Although it rained**, we went out.","commonMistakes":["Do not normally combine although and but to mark the same relation in one standard sentence."],"examples":["“**Although** we had prepared the visitor guide, the supervisor asked for another check.”","“**Although** we had restored the old portrait, the supervisor asked for another check.”"],"skill":"form"},{"title":"Despite and in spite of","explanation":"Despite and in spite of take a noun phrase or -ing expression. To follow them with a finite clause, use the fact that. Despite does not itself take of.","pattern":"**Despite the rain**, we went out. / **Despite the fact that it rained**, we went out.","commonMistakes":["Despite of is not the standard phrase; use despite or in spite of."],"examples":["“Despite **preparing** the visitor guide, we still had plenty to do.”","“Despite **restoring** the old portrait, we still had plenty to do.”"],"skill":"meaning"},{"title":"Whereas and while","explanation":"Whereas and contrastive while compare two facts, preferences or situations. While also has a time meaning, so ensure that context makes the contrast clear. Whereas is particularly useful when balancing one fact against another.","pattern":"She likes tea, **whereas** he prefers coffee.","commonMistakes":["Whereas normally introduces a clause, not a noun phrase by itself."],"examples":["Choose the correct concession phrase: “**In spite of** the difficulty, we managed to prepare the visitor guide.”","Choose the correct concession phrase: “**In spite of** the difficulty, we managed to restore the old portrait.”"],"skill":"contrast"},{"title":"However and nevertheless","explanation":"However and nevertheless are linking adverbs, not ordinary coordinating conjunctions. They can start a new sentence or follow a semicolon between independent clauses. Their punctuation differs from but even when the contrast is similar.","pattern":"It rained**; however,** we went out.","commonMistakes":["It rained, however we went out is a comma splice in ordinary formal prose."],"examples":["Choose formal punctuation linking two complete clauses: “We prepared the visitor guide **;** however, the supervisor requested a change.”","Choose formal punctuation linking two complete clauses: “We restored the old portrait **;** however, the supervisor requested a change.”"],"skill":"application"}],"tips":[],"source":"seed","provenance":{"kind":"original-guidance-aligned","referenceIds":["bc-contrast"],"version":"core-2026-09-v3","reviewStatus":"automated-checked; educator-review-pending"},"chapter":{"introduction":["Show that two ideas contrast, or that something happens in spite of an obstacle.","The form tells you how to build the sentence; the context tells you why that form is useful. Read each section with both questions in mind. The examples make one contrast at a time, while the practice mixes the skills so that you learn to recognise the pattern yourself."],"rules":[{"title":"Although and even though","explanation":"Although, though and even though introduce a subordinate clause. They present information that contrasts with the main clause or might have led to a different expectation. Even though often makes the contrast stronger.","pattern":"**Although it rained**, we went out.","commonMistakes":["Do not normally combine although and but to mark the same relation in one standard sentence."],"examples":["“**Although** we had prepared the visitor guide, the supervisor asked for another check.”","“**Although** we had restored the old portrait, the supervisor asked for another check.”"],"skill":"form","id":"contrast-concession-foundation-1","domain":"adjuncts","referenceIds":["bc-contrast"],"readingVersion":"core-2026-09-v3"},{"title":"Despite and in spite of","explanation":"Despite and in spite of take a noun phrase or -ing expression. To follow them with a finite clause, use the fact that. Despite does not itself take of.","pattern":"**Despite the rain**, we went out. / **Despite the fact that it rained**, we went out.","commonMistakes":["Despite of is not the standard phrase; use despite or in spite of."],"examples":["“Despite **preparing** the visitor guide, we still had plenty to do.”","“Despite **restoring** the old portrait, we still had plenty to do.”"],"skill":"meaning","id":"contrast-concession-foundation-2","domain":"adjuncts","referenceIds":["bc-contrast"],"readingVersion":"core-2026-09-v3"},{"title":"Whereas and while","explanation":"Whereas and contrastive while compare two facts, preferences or situations. While also has a time meaning, so ensure that context makes the contrast clear. Whereas is particularly useful when balancing one fact against another.","pattern":"She likes tea, **whereas** he prefers coffee.","commonMistakes":["Whereas normally introduces a clause, not a noun phrase by itself."],"examples":["Choose the correct concession phrase: “**In spite of** the difficulty, we managed to prepare the visitor guide.”","Choose the correct concession phrase: “**In spite of** the difficulty, we managed to restore the old portrait.”"],"skill":"contrast","id":"contrast-concession-foundation-3","domain":"adjuncts","referenceIds":["bc-contrast"],"readingVersion":"core-2026-09-v3"},{"title":"However and nevertheless","explanation":"However and nevertheless are linking adverbs, not ordinary coordinating conjunctions. They can start a new sentence or follow a semicolon between independent clauses. Their punctuation differs from but even when the contrast is similar.","pattern":"It rained**; however,** we went out.","commonMistakes":["It rained, however we went out is a comma splice in ordinary formal prose."],"examples":["Choose formal punctuation linking two complete clauses: “We prepared the visitor guide **;** however, the supervisor requested a change.”","Choose formal punctuation linking two complete clauses: “We restored the old portrait **;** however, the supervisor requested a change.”"],"skill":"application","id":"contrast-concession-foundation-4","domain":"adjuncts","referenceIds":["bc-contrast"],"readingVersion":"core-2026-09-v3"},{"domain":"adjuncts","id":"conditional-alternatives","title":"Unless, provided that, as long as and in case","explanation":"Unless introduces an exception, often paraphrasable with if not. Provided that and as long as set a condition. In case normally explains a precaution against a possible event; it is not simply another spelling of if. Keep the intended relationship clear before choosing the connector.","pattern":"Take a torch **in case** it gets dark.","examples":["You may borrow it **provided that you return it**.","We will go **unless it rains**."],"commonMistakes":["I’ll take an umbrella in case it rains means taking it as a precaution. I’ll take one if it rains makes taking it dependent on the rain."],"referenceIds":["cambridge-comprehensive-scope"],"readingVersion":"core-2026-09-v4"},{"domain":"adjuncts","id":"even-if-even-though","title":"Even if, even though and whether…or","explanation":"Even though presents a concession treated as a fact. Even if considers a condition and says the result will hold despite it. Whether…or can present alternative conditions with the same outcome. Do not select only from the presence of an unexpected result; decide whether the condition is asserted as true.","pattern":"**Even though** it rained / **Even if** it rains","examples":["We went out **even though it was cold**.","We will finish **whether you help or not**."],"commonMistakes":["Even when often concerns an actual or recurring situation; even if often concerns a hypothetical one. Context can make the boundary less sharp."],"referenceIds":["cambridge-comprehensive-scope"],"readingVersion":"core-2026-09-v4"}],"recap":["**Although it rained**, we went out.","**Despite the rain**, we went out. / **Despite the fact that it rained**, we went out.","She likes tea, **whereas** he prefers coffee.","It rained**; however,** we went out."],"readingVersion":"core-2026-09-v4"},"stage":"4 · Connecting meanings","prerequisites":["linking-clauses"],"readingReferenceIds":["bc-contrast","cambridge-comprehensive-scope"]}'::jsonb FROM grammar.content_catalog_topics WHERE version='core-2026-09-v3' AND slug='contrast-concession'
